# This script will rank candidate failure-avoiding (generated by run/candidates.py) patterns through the following ranking distribution:
#  1. failure-free runs have total priority;
#  2. failing runs by maximum progress (`log/progress`), then steps survived;
#  3. within a group, by risk: largest predicted failure probability and
#     smallest margin to a failure rule;
#  4. task reward only breaks remaining ties

import argparse
import json
import pathlib

def get(row, key, default):
    value = row.get(key)
    return default if value is None else value

def rank_key(row):
    failed = row['failed']
    return (
        failed,
        not row['goal'],
        -get(row, 'max_progress', 0.0),
        -row['length'] if failed else 0,         
        get(row, 'max_pfail', 0.0),               
        -get(row, 'min_margin', 0.0),             
        -get(row, 'score', 0.0),
    )    

def main():
  parser = argparse.ArgumentParser()
  parser.add_argument('candidates', type=pathlib.Path)
  parser.add_argument('--top', type=int, default=10)
  args = parser.parse_args()

  lines = (args.candidates / 'summary.jsonl').read_text().splitlines()
  rows = [json.loads(line) for line in lines if line.strip()]
  ranked = sorted(rows, key=rank_key)

  with open(args.candidates / 'ranked.jsonl', 'w') as f:
    for rank, row in enumerate(ranked):
      f.write(json.dumps({'rank': rank, **row}) + '\n')

  for rank, row in enumerate(ranked[:args.top]):
    print(rank, row)


if __name__ == '__main__':
  main()   